// 抑制(漢字を出さない)/抑制しない(かなを先頭にして漢字はその後ろ)を選ぶ
enum KanaGakiCategory: String, CaseIterable {
    case adverb
    case conjunction
    case auxiliary
    case formalNoun
    case demonstrative
    case adverbKanaFirst

    var title: String {
        switch self {
        case .adverb: return "副詞"
        case .conjunction: return "接続詞"
        case .auxiliary: return "補助の言葉・挨拶"
        case .formalNoun: return "形式名詞"
        case .demonstrative: return "指示語・代名詞"
        case .adverbKanaFirst: return "副詞(漢字も残す)"
        }
    }

    var settingsKey: String {
        "kanaGakiSuppress" + rawValue.prefix(1).uppercased() + rawValue.dropFirst()
    }

    // 初期設定で抑制するか(plist の見出しの default=off の仲間は かな先頭で漢字も残す。3552)
    var suppressedByDefault: Bool {
        switch self {
        case .adverb: return true
        case .conjunction: return true
        case .auxiliary: return true
        case .formalNoun: return true
        case .demonstrative: return true
        case .adverbKanaFirst: return false
        }
    }
}

